def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    op = [h[1] for h in history]
    my = [h[0] for h in history]
    opD = op.count('D')
    myD = my.count('D')
    last_my = my[-1]
    last_op = op[-1]

    # Endgame exploitation is only worth it against unconditional cooperators.
    remaining = 100 - n
    if remaining <= 1:
        if opD == 0:
            return 'D'
        if opD * 4 < n:
            return 'D'
        return 'C'
    if remaining <= 3:
        if opD == 0:
            return 'D'
        if opD * 5 < n:
            return 'D'
        return 'D' if last_op == 'D' else 'C'

    # Detect unconditional cooperation and exploit with controlled probes.
    if opD == 0:
        if n >= 20 and n % 11 == 0:
            return 'D'
        return 'C'

    # Detect heavy defection and punish.
    if opD * 3 >= n * 2 and n >= 6:
        return 'D'

    # Recovery logic: if opponent just cooperated after defection, reciprocate.
    if last_op == 'C':
        if last_my == 'D':
            return 'C'
        if n >= 3 and op[-3:] == ['D', 'D', 'D']:
            if rng.random() < 0.4:
                return 'D'
            return 'C'
        if opD * 4 >= n and n >= 10:
            if rng.random() < 0.25:
                return 'D'
        return 'C'

    # Opponent defected last round.
    # If our last was D too, be willing to restore cooperation.
    if last_my == 'D':
        recent_d = 0
        for i in range(max(0, n - 4), n):
            if op[i] == 'D':
                recent_d += 1
        if recent_d <= 2:
            return 'C'
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # We cooperated, they defected: retaliate but not forever.
    recent_d = 0
    for i in range(max(0, n - 5), n):
        if op[i] == 'D':
            recent_d += 1
    if recent_d >= 4:
        return 'D'
    if n >= 4 and op[-2] == 'D' and op[-3] == 'D':
        return 'D'
    if rng.random() < 0.2:
        return 'C'
    return 'D'
